(() => {
  'use strict';
  const engine = globalThis.AlarmPuzzleEngine;
  const scenes = globalThis.AlarmPuzzleScenes;
  function attach(document, view) {
    const get = (id) => document.getElementById(id);
    const status = get('status');
    const restart = get('restart');
    let scene = scenes.balloons;
    let state = engine.createState(scene.itemIds.length);
    let gesture = null;
    function render() {
      get('counter').textContent = `수거 ${state.cleared} / ${state.total}`;
      get('finish').hidden = state.phase !== 'done';
      get('coupon-mouth').classList.toggle('ready', scene.id === 'coupons' && state.ready);
      get('coupon-mouth').style.setProperty('--near', String(state.amount));
      scene.itemIds.forEach((id, index) => {
        const item = get(id);
        const control = get(scene.controlIds[index]);
        const active = state.active === index;
        item.classList.toggle('collected', state.items[index]);
        item.classList.toggle('held', active);
        item.classList.toggle('ready', active && state.ready);
        // Keep the final pose while a collected paper folds into the mouth.
        if (!state.items[index]) {
          item.style.setProperty('--x', `${active ? state.x : 0}px`);
          item.style.setProperty('--y', `${active ? state.y : 0}px`);
        }
        item.style.setProperty('--air', String(active ? state.amount : state.items[index] ? 1 : 0));
        item.setAttribute('aria-hidden', String(state.items[index]));
        control.disabled = state.items[index];
        control.setAttribute('aria-pressed', String(active));
      });
    }
    function showScene() {
      get('workshop').setAttribute('data-scene', scene.id);
      for (const option of Object.values(scenes)) {
        get(`${option.id}-panel`).hidden = option.id !== scene.id;
        get(`choose-${option.id}`).setAttribute('aria-pressed', String(option.id === scene.id));
      }
      get('scene-title').textContent = scene.title;
      get('scene-accent').textContent = scene.accent;
      get('scene-intro').textContent = scene.intro;
      get('play-scene').setAttribute('aria-label', scene.id === 'balloons' ? '마개가 달린 광고 풍선 세 개' : '쿠폰 두 장과 종이 회수구');
      get('finish-copy').textContent = scene.finish;
    }
    function stop(cancelled) {
      if (!gesture) return;
      const previous = state.cleared;
      const owned = gesture;
      // Clear ownership first: releasePointerCapture may synchronously re-enter.
      gesture = null;
      if (owned.pointerId !== null && owned.element.hasPointerCapture(owned.pointerId)) owned.element.releasePointerCapture(owned.pointerId);
      state = cancelled ? engine.cancel(state) : engine.release(state);
      status.textContent = cancelled ? '물체가 제자리로 돌아왔어요.' :
        state.phase === 'done' ? '화면이 조용해졌어요.' :
        state.cleared > previous ? `${scene.noun} 하나가 사라졌어요.` : scene.miss;
      render();
      if (state.phase === 'done') restart.focus();
      else if (state.cleared > previous) get(scene.controlIds[state.items.findIndex((collected) => !collected)]).focus();
    }
    function start(option, index, element, pointerId, x = 0, y = 0) {
      if (option.id !== scene.id || gesture || state.items[index] || state.phase === 'done') return false;
      state = engine.begin(state, index);
      // Snap back from any return transition before measuring the next gesture.
      render();
      gesture = { index, element, pointerId, startX: x, startY: y, origin: element.getBoundingClientRect() };
      if (pointerId !== null) element.setPointerCapture(pointerId);
      return true;
    }
    function update(dx, dy) {
      state = scene.id === 'balloons' ? engine.valve(state, dy) :
        engine.paper(state, dx, dy, gesture.origin, get('coupon-mouth').getBoundingClientRect());
      status.textContent = state.ready ? scene.ready : scene.moving;
      render();
    }
    function outside(event) {
      return !Number.isFinite(event.clientX) || !Number.isFinite(event.clientY) ||
        event.clientX < 0 || event.clientY < 0 || event.clientX >= view.innerWidth || event.clientY >= view.innerHeight;
    }
    for (const option of Object.values(scenes)) {
      option.controlIds.forEach((id, index) => {
        const element = get(id);
        const owns = (event) => gesture?.element === element && gesture.pointerId === event.pointerId;
        element.addEventListener('pointerdown', (event) => {
          if (event.button !== 0 || outside(event)) return;
          event.preventDefault();
          start(option, index, element, event.pointerId, event.clientX, event.clientY);
        });
        element.addEventListener('pointermove', (event) => {
          if (!owns(event)) return;
          if (outside(event)) return stop(true);
          update(event.clientX - gesture.startX, event.clientY - gesture.startY);
        });
        element.addEventListener('pointerup', (event) => {
          if (!owns(event)) return;
          if (outside(event)) return stop(true);
          // A final release can arrive without a matching move event.
          update(event.clientX - gesture.startX, event.clientY - gesture.startY);
          stop(false);
        });
        for (const reason of ['pointercancel', 'lostpointercapture']) {
          element.addEventListener(reason, (event) => { if (owns(event)) stop(true); });
        }
        element.addEventListener('blur', () => { if (gesture?.element === element && gesture.pointerId === null) stop(true); });
        element.addEventListener('keydown', (event) => {
          if (![' ', 'Enter', 'Escape', 'ArrowDown', 'ArrowUp', 'ArrowLeft', 'ArrowRight'].includes(event.key)) return;
          if (option.id !== scene.id) return;
          event.preventDefault();
          if (event.repeat || (gesture && (gesture.element !== element || gesture.pointerId !== null))) return;
          if (event.key === 'Escape') return stop(true);
          if (event.key === ' ' || event.key === 'Enter') {
            if (gesture) stop(false);
            else start(option, index, element, null);
            return;
          }
          if (!gesture) return;
          const dx = state.x + (event.key === 'ArrowRight' ? 16 : event.key === 'ArrowLeft' ? -16 : 0);
          const dy = state.y + (event.key === 'ArrowDown' ? 16 : event.key === 'ArrowUp' ? -16 : 0);
          const rect = gesture.origin;
          update(Math.max(-rect.left, Math.min(view.innerWidth - rect.right, dx)),
            Math.max(-rect.top, Math.min(view.innerHeight - rect.bottom, dy)));
        });
      });
      get(`choose-${option.id}`).addEventListener('click', () => { if (option.id !== scene.id) reset(option); });
    }
    for (const reason of ['blur', 'pagehide', 'resize', 'scroll']) view.addEventListener(reason, () => stop(true));
    view.addEventListener('pointerout', (event) => {
      if (gesture?.pointerId === event.pointerId && event.relatedTarget === null) stop(true);
    });
    document.addEventListener('visibilitychange', () => { if (document.hidden) stop(true); });
    function reset(nextScene) {
      stop(true);
      scene = nextScene;
      state = engine.createState(scene.itemIds.length);
      showScene();
      status.textContent = scene.start;
      render();
      get(scene.controlIds[0]).focus();
    }
    restart.addEventListener('click', () => reset(scene));
    showScene();
    status.textContent = scene.start;
    render();
    return { getState: () => ({ ...state, items: [...state.items] }), getScene: () => scene.id };
  }
  globalThis.AlarmPuzzleApp = Object.freeze({ attach });
  if (typeof document !== 'undefined') attach(document, globalThis);
})();

