/* Classic script: the puzzle also runs directly from disk. */
(() => {
  'use strict';
  const VALVE_TRAVEL = 52;
  const emptyGesture = { active: null, x: 0, y: 0, amount: 0, ready: false };
  const clamp = (value, low, high) => Math.max(low, Math.min(high, value));
  function createState(total = 3) {
    if (!Number.isInteger(total) || total < 1) throw new RangeError('Invalid item count');
    return { total, items: Array(total).fill(false), cleared: 0, phase: 'playing', ...emptyGesture };
  }
  function begin(state, index) {
    if (state.phase !== 'playing' || state.active !== null || !Number.isInteger(index) ||
        index < 0 || index >= state.total || state.items[index]) return state;
    return { ...state, ...emptyGesture, active: index };
  }
  function cancel(state) { return { ...state, ...emptyGesture }; }
  function valve(state, dy) {
    if (state.active === null) return state;
    const y = Number.isFinite(dy) ? clamp(dy, 0, VALVE_TRAVEL) : 0;
    return { ...state, x: 0, y, amount: y / VALVE_TRAVEL, ready: y === VALVE_TRAVEL };
  }
  function paper(state, dx, dy, origin, slot) {
    if (state.active === null) return state;
    if (![dx, dy, origin.left, origin.width, origin.bottom, slot.left, slot.right, slot.top, slot.bottom].every(Number.isFinite)) {
      return { ...state, x: 0, y: 0, amount: 0, ready: false };
    }
    // Match the paper's lower edge to the visible mouth, not the pointer position.
    const tipY = origin.bottom + dy;
    const gapX = Math.max(slot.left - 14 - (origin.left + dx), 0,
      origin.left + origin.width + dx - (slot.right + 14));
    const gapY = Math.max(slot.top - 14 - tipY, 0, tipY - (slot.bottom + 14));
    const moved = Math.hypot(dx, dy) >= 8;
    return { ...state, x: dx, y: dy,
      amount: moved ? 1 - clamp(Math.hypot(gapX, gapY) / 100, 0, 1) : 0,
      ready: moved && gapX === 0 && gapY === 0 };
  }
  function release(state) {
    if (state.active === null || !state.ready) return cancel(state);
    const items = state.items.map((collected, index) => collected || index === state.active);
    const cleared = items.filter(Boolean).length;
    return { ...cancel(state), items, cleared, phase: cleared === state.total ? 'done' : 'playing' };
  }
  globalThis.AlarmPuzzleEngine = Object.freeze({ createState, begin, cancel, valve, paper, release, VALVE_TRAVEL });
})();

