import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import vm from 'node:vm';

const source = (path) => readFileSync(new URL(`../${path}`, import.meta.url), 'utf8');
const context = vm.createContext({});
for (const path of ['src/scenes.js', 'src/puzzle.js', 'src/app.js']) vm.runInContext(source(path), context);
const engine = context.AlarmPuzzleEngine;
const plain = (value) => JSON.parse(JSON.stringify(value));
const unplug = (state, index) => engine.release(engine.valve(engine.begin(state, index), 52));
const rect = (left, top, width, height) => ({ left, top, width, height, right: left + width, bottom: top + height });
const paperOrigin = rect(40, 90, 280, 130);
const mouth = rect(20, 510, 360, 44);

test('independent objects begin full; selecting any object does not change another', () => {
  const initial = engine.createState();
  const held = engine.valve(engine.begin(initial, 2), 26);
  assert.equal(held.active, 2);
  assert.equal(held.amount, .5);
  assert.equal(held.cleared, 0);
  assert.deepEqual(plain(initial.items), [false, false, false]);
  assert.equal(initial.active, null);
});

test('one complete unplug removes the selected balloon, in any order', () => {
  for (const order of [[2, 0, 1], [1, 2, 0], [0, 1, 2]]) {
    let state = engine.createState();
    order.forEach((index, step) => {
      state = unplug(state, index);
      assert.equal(state.items[index], true);
      assert.equal(state.cleared, step + 1);
    });
    assert.equal(state.phase, 'done');
    assert.deepEqual(plain(unplug(state, 0)), plain(state));
  }
});

test('short, wrong-direction and invalid pulls never accumulate hidden repetitions', () => {
  let state = engine.createState();
  for (const dy of [0, -52, 26, 51.9, NaN, Infinity, undefined, 26, 26, 26]) {
    state = engine.release(engine.valve(engine.begin(state, 0), dy));
    assert.equal(state.cleared, 0);
    assert.equal(state.amount, 0);
  }
  assert.equal(engine.valve(engine.begin(state, 0), 500).y, 52);
});

test('cancel rolls back the held object, preserving another collected item', () => {
  const before = unplug(engine.createState(), 2);
  assert.deepEqual(plain(engine.cancel(engine.valve(engine.begin(before, 0), 52))), plain(before));
});

test('invalid selection and a second simultaneous grab cannot corrupt state', () => {
  let state = unplug(engine.createState(), 1);
  for (const index of [-1, 3, NaN, 1, .5]) assert.equal(engine.begin(state, index), state);
  state = engine.begin(state, 2);
  assert.equal(engine.begin(state, 0), state);
  assert.throws(() => engine.createState(0));
});

test('coupon destination depends on its lower edge, not a fixed drag distance', () => {
  const held = engine.begin(engine.createState(2), 1);
  assert.equal(engine.paper(held, 0, 312, paperOrigin, mouth).ready, true);
  assert.equal(engine.paper(held, 250, 312, paperOrigin, mouth).ready, false);
  assert.equal(engine.paper(held, 170, 312, paperOrigin, mouth).ready, false, 'a center inside the mouth is insufficient when the edge sticks out');
  assert.equal(engine.paper(held, 0, 500, paperOrigin, mouth).ready, false);
  assert.equal(engine.paper(held, 0, -100, paperOrigin, mouth).ready, false);
  const shiftedMouth = rect(120, 610, 280, 44);
  assert.equal(engine.paper(held, 0, 312, paperOrigin, shiftedMouth).ready, false);
  assert.equal(engine.paper(held, 80, 412, paperOrigin, shiftedMouth).ready, true);
});

test('coupon approach reacts continuously and loses readiness after leaving the mouth', () => {
  let state = engine.begin(engine.createState(2), 0);
  state = engine.paper(state, 0, 240, paperOrigin, mouth);
  assert.ok(state.amount > 0 && state.amount < 1);
  state = engine.paper(state, 0, 312, paperOrigin, mouth);
  assert.equal(state.ready, true);
  state = engine.paper(state, 0, 100, paperOrigin, mouth);
  assert.equal(engine.release(state).cleared, 0);
});

test('coupon overlap requires deliberate movement; invalid coordinates clear readiness', () => {
  const held = engine.begin(engine.createState(2), 0);
  assert.equal(engine.paper(held, 0, 0, rect(40, 402, 280, 130), mouth).ready, false);
  const ready = engine.paper(held, 0, 312, paperOrigin, mouth);
  for (const dx of [NaN, Infinity, undefined]) {
    assert.equal(engine.release(engine.paper(ready, dx, 312, paperOrigin, mouth)).cleared, 0);
  }
});

class Element {
  constructor() {
    this.handlers = {};
    this.style = { setProperty(name, value) { this[name] = value; } };
    this.classes = new Set();
    this.classList = { toggle: (name, value) => value ? this.classes.add(name) : this.classes.delete(name) };
    this.attributes = {};
    this.captures = new Set();
    this.hidden = false;
    this.disabled = false;
    this.textContent = '';
    this.focused = false;
    this.rect = rect(80, 100, 54, 44);
  }
  addEventListener(name, handler) { (this.handlers[name] ??= []).push(handler); }
  setAttribute(name, value) { this.attributes[name] = value; }
  setPointerCapture(id) { this.captures.add(id); }
  hasPointerCapture(id) { return this.captures.has(id); }
  releasePointerCapture(id) { this.captures.delete(id); this.emit('lostpointercapture', { pointerId: id }); }
  focus() { this.focused = true; }
  getBoundingClientRect() { return { ...this.rect }; }
  emit(name, fields = {}) {
    const event = { pointerId: 1, clientX: 100, clientY: 120, button: 0, repeat: false, preventDefault() {}, ...fields };
    for (const handler of this.handlers[name] ?? []) handler(event);
  }
}

function fixture(scene = 'balloons') {
  // Only create real HTML anchors: missing controller anchors fail at attachment.
  const elements = Object.fromEntries([...source('index.html').matchAll(/id="([^"]+)"/g)].map((match) => [match[1], new Element()]));
  elements['coupon-0'].rect = paperOrigin;
  elements['coupon-1'].rect = rect(60, 260, 280, 130);
  elements['coupon-mouth'].rect = mouth;
  const document = new Element();
  document.getElementById = (id) => elements[id];
  const view = new Element();
  view.innerWidth = 400;
  view.innerHeight = 900;
  const app = context.AlarmPuzzleApp.attach(document, view);
  if (scene === 'coupons') elements['choose-coupons'].emit('click');
  const drag = (id, dx = 0, dy = 52, pointerId = 1) => {
    const element = elements[id];
    const clientX = element.rect.left + 20;
    const clientY = element.rect.top + 20;
    element.emit('pointerdown', { pointerId, clientX, clientY });
    element.emit('pointermove', { pointerId, clientX: clientX + dx, clientY: clientY + dy });
    element.emit('pointerup', { pointerId, clientX: clientX + dx, clientY: clientY + dy });
  };
  const collect = (index) => {
    if (app.getScene() === 'balloons') drag(`valve-${index}`);
    else drag(`coupon-${index}`, 0, mouth.top + 22 - elements[`coupon-${index}`].rect.bottom);
  };
  return { elements, view, document, app, drag, collect };
}

