for (const scene of ['balloons', 'coupons']) {
  const id = scene === 'balloons' ? 'valve-0' : 'coupon-0';
  const dy = scene === 'balloons' ? 52 : 312;
  test(`${scene}: a tap, repeated clicks or a wrong-direction drag cannot solve`, () => {
    const { elements, app, drag } = fixture(scene);
    drag(id, 0, 0);
    drag(id, 0, -20);
    for (let i = 0; i < 5; i++) elements[id].emit('click');
    assert.equal(app.getState().cleared, 0);
  });
  test(`${scene}: a second pointer, other object and right button cannot take ownership`, () => {
    const { elements, app } = fixture(scene);
    const other = elements[scene === 'balloons' ? 'valve-1' : 'coupon-1'];
    elements[id].emit('pointerdown', { button: 2 });
    elements[id].emit('pointerup', { clientY: 120 + dy });
    assert.equal(app.getState().cleared, 0);
    elements[id].emit('pointerdown');
    other.emit('pointerdown', { pointerId: 2 });
    other.emit('pointerup', { pointerId: 2, clientY: 120 + dy });
    elements[id].emit('pointermove', { pointerId: 2, clientY: 120 + dy });
    assert.equal(app.getState().active, 0);
    assert.equal(app.getState().amount, 0);
    elements[id].emit('pointerup', { clientY: 120 + dy });
    assert.equal(app.getState().cleared, 1);
  });
  for (const reason of ['pointercancel', 'lostpointercapture', 'blur', 'pagehide', 'hidden', 'resize', 'scroll', 'window-exit']) {
    test(`${scene}: ${reason} cancels preview and ignores late release, preserving other items`, () => {
      const { elements, app, view, document, collect } = fixture(scene);
      collect(1);
      elements[id].emit('pointerdown');
      elements[id].emit('pointermove', { clientY: 120 + dy });
      assert.equal(app.getState().ready, true);
      if (reason === 'hidden') { document.hidden = true; document.emit('visibilitychange'); }
      else if (reason === 'window-exit') view.emit('pointerout', { relatedTarget: null });
      else if (['pointercancel', 'lostpointercapture'].includes(reason)) elements[id].emit(reason);
      else view.emit(reason);
      elements[id].emit('pointerup', { clientY: 120 + dy });
      assert.equal(app.getState().cleared, 1);
      assert.equal(app.getState().active, null);
      assert.equal(elements[id].hasPointerCapture(1), false);
      document.hidden = false;
      collect(0);
      assert.equal(app.getState().cleared, 2);
    });
  }
  test(`${scene}: all viewport edges cancel on movement and on release`, () => {
    for (const outside of [{ clientX: -1 }, { clientX: 400 }, { clientY: -1 }, { clientY: 900 }]) {
      for (const event of ['pointermove', 'pointerup']) {
        const { elements, app } = fixture(scene);
        elements[id].emit('pointerdown');
        elements[id].emit('pointermove', { clientY: 120 + dy });
        elements[id].emit(event, { clientY: 120 + dy, ...outside });
        elements[id].emit('pointerup', { clientY: 120 + dy });
        assert.equal(app.getState().cleared, 0);
      }
    }
  });
  test(`${scene}: two full plays and repeated restart restore every object`, () => {
    const { elements, app, collect } = fixture(scene);
    const total = scene === 'balloons' ? 3 : 2;
    for (let round = 0; round < 2; round++) {
      for (let index = total - 1; index >= 0; index--) collect(index);
      assert.equal(app.getState().phase, 'done');
      assert.equal(elements.finish.hidden, false);
      assert.equal(elements.restart.focused, true);
      elements.restart.emit('click');
      elements.restart.emit('click');
      assert.deepEqual(plain(app.getState()), plain(engine.createState(total)));
      assert.equal(elements.finish.hidden, true);
      assert.equal(app.getScene(), scene);
      for (const item of context.AlarmPuzzleScenes[scene].itemIds) assert.equal(elements[item].classes.has('collected'), false);
    }
  });
  test(`${scene}: restart during manipulation invalidates old pointer events`, () => {
    const { elements, app, collect } = fixture(scene);
    collect(1);
    elements[id].emit('pointerdown');
    elements[id].emit('pointermove', { clientY: 120 + dy });
    elements.restart.emit('click');
    elements[id].emit('pointerup', { clientY: 120 + dy });
    assert.equal(app.getState().cleared, 0);
    assert.equal(app.getState().active, null);
    assert.equal(elements[id].hasPointerCapture(1), false);
  });
}

